export class InputController{constructor(){this.keys=new Set();this.x=0;this.z=0;this.boost=false;this.jump=false;this.action=false;this.look=0;addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;this.keys.add(e.code);if(e.code==='Space')this.jump=true;if(e.code==='KeyE')this.action=true});addEventListener('keyup',e=>this.keys.delete(e.code));addEventListener('blur',()=>{this.keys.clear();this.x=this.z=0});const s=document.querySelector('#stick'),knob=s.firstElementChild;const move=e=>{const r=s.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/45,z=(e.clientY-r.top-r.height/2)/45;const l=Math.max(1,Math.hypot(x,z));this.x=x/l;this.z=z/l;knob.style.transform=`translate(${this.x*34}px,${this.z*34}px)`};s.onpointerdown=e=>{s.setPointerCapture(e.pointerId);move(e)};s.onpointermove=e=>{if(s.hasPointerCapture(e.pointerId))move(e)};s.onpointerup=s.onpointercancel=()=>{this.x=this.z=0;knob.style.transform=''};document.querySelector('#jump').onpointerdown=()=>this.jump=true;document.querySelector('#action').onpointerdown=()=>this.action=true;const boost=document.querySelector('#boost');boost.onpointerdown=e=>{boost.setPointerCapture(e.pointerId);this.boost=true};boost.onpointerup=boost.onpointercancel=()=>this.boost=false;const canvas=document.querySelector('canvas');canvas.onpointerdown=e=>{this.drag=e.clientX;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(canvas.hasPointerCapture(e.pointerId)){this.look+=(e.clientX-this.drag)*.006;this.drag=e.clientX}}}axis(){return{x:this.x+(this.keys.has('KeyD')?1:0)-(this.keys.has('KeyA')?1:0),z:this.z+(this.keys.has('KeyS')?1:0)-(this.keys.has('KeyW')?1:0)}}}
